#include <stdio.h>
#include <string.h>

#define MOD 1000000007

int dp[205][205][105]; // dp[x][y][k] = ways to reach (x,y) with k detours used

int main() {
    int N, M, K;
    scanf("%d %d %d", &N, &M, &K);

    memset(dp, 0, sizeof(dp));
    dp[0][0][0] = 1;

    int maxCoord = N + M + K; // safe bound

    for (int x = 0; x <= maxCoord; x++) {
        for (int y = 0; y <= maxCoord; y++) {
            for (int k = 0; k <= K; k++) {
                if (dp[x][y][k] == 0) continue;
                int val = dp[x][y][k];

                // move right
                if (x + 1 <= maxCoord)
                    dp[x+1][y][k] = (dp[x+1][y][k] + val) % MOD;
                // move up
                if (y + 1 <= maxCoord)
                    dp[x][y+1][k] = (dp[x][y+1][k] + val) % MOD;
                // move left (detour), if x>0
                if (x > 0 && k < K)
                    dp[x-1][y][k+1] = (dp[x-1][y][k+1] + val) % MOD;
                // move down (detour), if y>0
                if (y > 0 && k < K)
                    dp[x][y-1][k+1] = (dp[x][y-1][k+1] + val) % MOD;
            }
        }
    }

    int ans = 0;
    // sum over all states at (N,M) with exactly K detours
    for (int x = 0; x <= maxCoord; x++) {
        for (int y = 0; y <= maxCoord; y++) {
            ans = (ans + dp[x][y][K]) % MOD;
        }
    }

    printf("%d\n", ans);
    return 0;
}

