#define MOD 1000000007LL

/*
Let:
R = number of right moves
U = number of up moves
L = number of left moves
D = number of down moves

We start at (0,0) and end at (N,M), so:
R - L = N
U - D = M

A detour is a left or down move, and exactly K detours means:
L + D = K

Thus total right/up counts are:
R + U = N + M + K

Interpretation:
A valid path is any sequence of horizontal and vertical steps where:
- among horizontal steps, there are N+L rights and L lefts, never making x < 0
- among vertical steps, there are M+D ups and D downs, never making y < 0
- total detours K = L + D

Horizontal and vertical behaviors are independent except for interleaving.
For fixed L and D=K-L:
- number of valid horizontal sequences =
    ballot(N+2L, L) = C(N+2L, L) - C(N+2L, L-1)
- number of valid vertical sequences =
    ballot(M+2D, D) = C(M+2D, D) - C(M+2D, D-1)
- number of ways to interleave the horizontal and vertical steps =
    C((N+M+2K), N+2L)

So answer:
sum_{L=0..K} interleave * horiz * vert

We precompute factorials up to N+M+2K.
*/

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

static long long comb(int n, int k, long long *fact, long long *invfact) {
    if (k < 0 || k > n) return 0;
    return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD;
}

int main(void) {
    int N, M, K;
    if (scanf("%d %d %d", &N, &M, &K) != 3) return 0;

    int MAX = N + M + 2 * K;
    long long fact[MAX + 1], invfact[MAX + 1];

    fact[0] = 1;
    for (int i = 1; i <= MAX; i++) fact[i] = fact[i - 1] * i % MOD;
    invfact[MAX] = mod_pow(fact[MAX], MOD - 2);
    for (int i = MAX; i > 0; i--) invfact[i - 1] = invfact[i] * i % MOD;

    long long ans = 0;

    for (int L = 0; L <= K; L++) {
        int D = K - L;

        int htot = N + 2 * L;
        int vtot = M + 2 * D;
        int total = htot + vtot;

        long long horiz = (comb(htot, L, fact, invfact) - comb(htot, L - 1, fact, invfact)) % MOD;
        if (horiz < 0) horiz += MOD;

        long long vert = (comb(vtot, D, fact, invfact) - comb(vtot, D - 1, fact, invfact)) % MOD;
        if (vert < 0) vert += MOD;

        long long interleave = comb(total, htot, fact, invfact);

        long long add = interleave * horiz % MOD * vert % MOD;
        ans += add;
        if (ans >= MOD) ans -= MOD;
    }

    printf("%lld\n", ans % MOD);
    return 0;
}

