#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    cin >> N >> M >> K;

    // dp[x][y][k][s]
    // s = 0 : currently before the first visit to (N, M)
    // s = 1 : after the first visit to (N, M), before the first visit to (0, 0)
    // s = 2 : after visiting (0, 0) after reaching (N, M)
    //
    // We only need x,y in [0..N+K], [0..M+K], because with exactly K detours
    // (left/down moves), the coordinates can exceed N,M by at most K.
    //
    // Each move:
    // Right/Up   : does not increase detours
    // Left/Down  : increases detours by 1
    //
    // Valid final states:
    //   - at (N,M), any stage, with exactly K detours
    //   - at (0,0), stage 2, with exactly K detours
    //
    // This models the statement:
    // before K detours are completed, after first reaching school you may continue,
    // and at some point you may return to home; after returning home, you may go again
    // toward school, but cannot visit home again because coordinates are nonnegative.

    int X = N + K;
    int Y = M + K;

    auto idx = [Y, K](int x, int y, int k, int s) {
        return (((x * (Y + 1) + y) * (K + 1) + k) * 3 + s);
    };

    vector<int64> dp((X + 1) * (Y + 1) * (K + 1) * 3, 0);
    dp[idx(0, 0, 0, 0)] = 1;

    for (int k = 0; k <= K; ++k) {
        for (int sum = 0; sum <= X + Y; ++sum) {
            for (int x = 0; x <= X; ++x) {
                int y = sum - x;
                if (y < 0 || y > Y) continue;

                for (int s = 0; s < 3; ++s) {
                    int64 cur = dp[idx(x, y, k, s)];
                    if (!cur) continue;

                    int ns = s;
                    if (s == 0 && x == N && y == M) ns = 1;
                    if (s == 1 && x == 0 && y == 0) ns = 2;

                    if (ns != s) {
                        dp[idx(x, y, k, ns)] += cur;
                        dp[idx(x, y, k, s)] = 0;
                        cur = 0;
                        continue;
                    }

                    // Right
                    if (x + 1 <= X) {
                        int s2 = s;
                        if (s2 == 0 && x + 1 == N && y == M) s2 = 1;
                        dp[idx(x + 1, y, k, s2)] += cur;
                    }
                    // Up
                    if (y + 1 <= Y) {
                        int s2 = s;
                        if (s2 == 0 && x == N && y + 1 == M) s2 = 1;
                        dp[idx(x, y + 1, k, s2)] += cur;
                    }
                    // Left = detour
                    if (k + 1 <= K && x - 1 >= 0) {
                        int s2 = s;
                        if (s2 == 1 && x - 1 == 0 && y == 0) s2 = 2;
                        dp[idx(x - 1, y, k + 1, s2)] += cur;
                    }
                    // Down = detour
                    if (k + 1 <= K && y - 1 >= 0) {
                        int s2 = s;
                        if (s2 == 1 && x == 0 && y - 1 == 0) s2 = 2;
                        dp[idx(x, y - 1, k + 1, s2)] += cur;
                    }
                }
            }
        }
    }

    int64 ans = 0;
    for (int s = 0; s < 3; ++s) ans += dp[idx(N, M, K, s)];
    ans += dp[idx(0, 0, K, 2)];

    cout << ans << '\n';
    return 0;
}

