public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), M = sc.nextInt(), K = sc.nextInt();

        BigInteger ans = BigInteger.ZERO;
        for (int L = 0; L <= K; L++) {
            int D = K - L;
            BigInteger xPaths = comb(N + 2*L, L).subtract(L > 0 ? comb(N + 2*L, L-1) : BigInteger.ZERO);
            BigInteger yPaths = comb(M + 2*D, D).subtract(D > 0 ? comb(M + 2*D, D-1) : BigInteger.ZERO);
            BigInteger interleave = comb(N + M + 2*K, N + 2*L);
            ans = ans.add(interleave.multiply(xPaths).multiply(yPaths));
        }
        System.out.println(ans);
    }

    static BigInteger comb(int n, int r) {
        if (r < 0 || r > n) return BigInteger.ZERO;
        BigInteger res = BigInteger.ONE;
        for (int i = 0; i < r; i++) {
            res = res.multiply(BigInteger.valueOf(n - i)).divide(BigInteger.valueOf(i + 1));
        }
        return res;
    }
}

