/*
We count walks on the nonnegative grid from (0,0) to (N,M),
using steps R=(+1,0), U=(0,+1), L=(-1,0), D=(0,-1),
such that the total number of detour steps (L or D) is exactly K.

Observation:
If there are a left-step count a and down-step count b, then to end at (N,M),
we must have right-step count N + a and up-step count M + b.
So total length is N + M + 2(a+b), where a+b = K.

Ignoring the nonnegative-boundary restriction, for fixed (a,b) the number of
such sequences is:
  (N+M+2K)! / ((N+a)! (M+b)! a! b!)

We must enforce that during the walk x,y never become negative.
The x- and y-motions are independent except for interleaving in time.
For a fixed choice of x-step subsequence (length N+2a) and y-step subsequence
(length M+2b), if each subsequence individually never goes negative, then any
interleaving also keeps both coordinates nonnegative.

Number of valid x-subsequences with +1 repeated N+a times and -1 repeated a times,
never going negative, is the ballot number:
  (N+1)/(N+a+1) * C(N+2a, a)
Similarly for y:
  (M+1)/(M+b+1) * C(M+2b, b)

Interleavings count:
  C(N+M+2K, N+2a)

So answer:
sum_{a=0..K, b=K-a}
  C(N+M+2K, N+2a)
  * BallotX(N,a)
  * BallotY(M,b)

This simplifies algebraically to:
  sum_{a=0..K}
    (N+M+2K)! * (N+1)(M+1)
    / [ (N+a+1)! a! (M+K-a+1)! (K-a)! ]

We compute exactly with BigInteger.
*/

public class Main {
    static BigInteger[] fact;

    static BigInteger C(int n, int r) {
        if (r < 0 || r > n) return BigInteger.ZERO;
        return fact[n].divide(fact[r].multiply(fact[n - r]));
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();
        int K = fs.nextInt();

        int max = N + M + 2 * K + 2;
        fact = new BigInteger[max + 1];
        fact[0] = BigInteger.ONE;
        for (int i = 1; i <= max; i++) fact[i] = fact[i - 1].multiply(BigInteger.valueOf(i));

        BigInteger totalFact = fact[N + M + 2 * K];
        BigInteger coef = BigInteger.valueOf((long)(N + 1)).multiply(BigInteger.valueOf((long)(M + 1)));

        BigInteger ans = BigInteger.ZERO;
        for (int a = 0; a <= K; a++) {
            int b = K - a;
            BigInteger denom = fact[N + a + 1]
                    .multiply(fact[a])
                    .multiply(fact[M + b + 1])
                    .multiply(fact[b]);
            BigInteger term = totalFact.multiply(coef).divide(denom);
            ans = ans.add(term);
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

MOD = 10**9 + 7

def modinv(a):
    return pow(a, MOD - 2, MOD)

def prepare_factorials(limit):
    fact = [1] * (limit + 1)
    invfact = [1] * (limit + 1)
    for i in range(1, limit + 1):
        fact[i] = fact[i-1] * i % MOD
    invfact[limit] = modinv(fact[limit])
    for i in range(limit - 1, -1, -1):
        invfact[i] = invfact[i+1] * (i+1) % MOD
    return fact, invfact

def comb(n, k, fact, invfact):
    if k < 0 or k > n:
        return 0
    return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD

def solve():
    N, M, K = map(int, input().split())
    limit = N + M + 2*K
    fact, invfact = prepare_factorials(limit)

    ans = (comb(N+M+2*K, N+K, fact, invfact) * comb(N+M+2*K, M+K, fact, invfact)) % MOD
    sub = (comb(N+M+2*K, N+K+1, fact, invfact) * comb(N+M+2*K, M+K+1, fact, invfact)) % MOD
    ans = (ans - sub) % MOD
    print(ans)

if __name__ == "__main__":
    solve()
